package com.rpb.reservation.workforce.payroll.governance;
import static com.rpb.reservation.workforce.payroll.governance.PayChangeDtos.*;
import com.rpb.reservation.walkin.api.CurrentActor;
import com.rpb.reservation.workforce.application.*;
import com.rpb.reservation.workforce.payroll.*;
import com.rpb.reservation.workforce.persistence.WorkforceEmployeeRepository;
import com.rpb.reservation.workforce.domain.WorkforceException;
import java.time.*;import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
@Service @Transactional(readOnly=true) public class PayChangeService {
 private final WorkforceAccess gate;private final PayrollAccess access;private final PayChangeRepository repository;private final PayrollConfigurationRepository configs;private final TemplatePublicationRepository publications;private final WorkforceEmployeeRepository employees;private final WorkforceAudit audit;private final PayChangeDrafts drafts;private final Clock clock;private final TemplatePublicationScope scope;
 public PayChangeService(WorkforceAccess gate,PayrollAccess access,PayChangeRepository repository,PayrollConfigurationRepository configs,TemplatePublicationRepository publications,WorkforceEmployeeRepository employees,WorkforceAudit audit,PayChangeDrafts drafts,Clock clock){this.gate=gate;this.access=access;this.repository=repository;this.configs=configs;this.publications=publications;this.employees=employees;this.audit=audit;this.drafts=drafts;this.clock=clock;scope=new TemplatePublicationScope(gate,publications);}
 private void authorize(CurrentActor actor,UUID store,UUID company,UUID employee){if(employee!=null){gate.enter(actor,store);var shop=publications.store(actor.tenantId(),store);if(!shop.active())throw WorkforceException.forbidden();access.enter(actor,store,company);access.employee(actor,company,employee);}else{var shop=scope.managed(actor,store);if(!company.equals(shop.companyId()))throw WorkforceException.forbidden();}}
 public Request detail(CurrentActor actor,UUID store,UUID id){gate.enter(actor,store);var r=repository.find(actor.tenantId(),id).orElseThrow(WorkforceException::missing);if(!r.storeId().equals(store))throw WorkforceException.forbidden();authorize(actor,store,r.companyId(),r.employeeId());return dated(actor.tenantId(),r);}
 public PayrollDtos.LineInput monthlyBaseline(CurrentActor actor,UUID store,UUID company,UUID employee,String month){authorize(actor,store,company,employee);return repository.monthlyBaseline(actor.tenantId(),company,employee,PayrollProfileValidation.month(month));}
 public List<Request> list(CurrentActor actor,UUID store,UUID company){gate.enter(actor,store);if(company==null)throw WorkforceException.invalid();var result=new ArrayList<Request>();for(var r:repository.list(actor.tenantId(),store,company)){try{authorize(actor,store,r.companyId(),r.employeeId());result.add(dated(actor.tenantId(),r));}catch(WorkforceException e){if(e.status()!=403)throw e;}}return List.copyOf(result);}
 @Transactional public Request save(CurrentActor actor,UUID store,UUID id,Write c){
  if(id==null||c==null||c.companyId()==null||c.expectedRevision()==null||c.expectedRevision()<0||((c.employeeId()==null)==(c.adoptionId()==null)))throw WorkforceException.invalid();authorize(actor,store,c.companyId(),c.employeeId());gate.sourceWrite(actor);repository.lock("subject:"+actor.tenantId()+":"+c.companyId()+":"+(c.employeeId()!=null?c.employeeId():c.adoptionId()));if(c.employeeId()!=null){configs.lockDefaults(actor.tenantId(),c.companyId());employees.lock(c.employeeId());}else{var a=publications.adoption(actor.tenantId(),store,c.companyId(),c.adoptionId());publications.lock("adoption:"+actor.tenantId()+":"+store+":"+a.masterId());}
  var old=repository.find(actor.tenantId(),id).orElse(null);var date=old!=null&&old.content().profile()!=null&&c.profile()==null?old.effectiveDate():drafts.date(actor,c);if(old!=null&&(!old.storeId().equals(store)||!old.companyId().equals(c.companyId())||!Objects.equals(old.employeeId(),c.employeeId())||!Objects.equals(old.adoptionId(),c.adoptionId())||!old.effectiveDate().equals(date)))throw WorkforceException.forbidden();
  var open=repository.open(actor.tenantId(),c.companyId(),c.employeeId(),c.adoptionId());if(old==null){old=open.stream().filter(r->r.effectiveDate().equals(date)||c.adoptionId()!=null).findFirst().orElse(null);if(old!=null&&!old.storeId().equals(store))throw WorkforceException.conflict();}
  if(old!=null&&!Set.of("draft","withdrawn").contains(old.status()))throw WorkforceException.conflict();var content=drafts.build(actor,store,date,c,old);if(old!=null&&old.revision()==c.expectedRevision()+1&&old.status().equals("draft")&&old.hash().equals(repository.hash(content)))return old;if((old==null?0:old.revision())!=c.expectedRevision())throw WorkforceException.conflict();
  for(var other:open)if(old==null||!other.id().equals(old.id()))for(var m:content.months())if(other.content().months().stream().anyMatch(x->x.month().equals(m.month())))throw WorkforceException.conflict();
  long revision=old==null?1:old.revision()+1;var event=new Event("save",revision,actor.actorId(),clock.instant(),content.reason());var events=new ArrayList<Event>(old==null?List.of():old.events());events.add(event);var next=new Request(old==null?id:old.id(),c.companyId(),store,c.employeeId(),date,c.adoptionId(),revision,repository.hash(content),"draft",null,content,old==null?actor.actorId():old.createdBy(),old==null?clock.instant():old.createdAt(),List.copyOf(events),"pending");repository.save(actor.tenantId(),next,true);repository.event(actor.tenantId(),next,event);audit.changed(actor,store,"pay-change.save",next.id(),old,next);return next;
 }
 @Transactional public Request action(CurrentActor actor,UUID store,UUID id,Action c){
  if(c==null||c.commandId()==null||c.expectedRevision()==null||c.expectedRevision()<1||c.expectedHash()==null||!Set.of("submit","withdraw","approve","reject").contains(c.action()==null?"":c.action()))throw WorkforceException.invalid();var initial=detail(actor,store,id);if(Set.of("approve","reject").contains(c.action()))gate.headOffice(actor);gate.sourceWrite(actor);repository.lock("command:"+c.commandId());repository.lock("subject:"+actor.tenantId()+":"+initial.companyId()+":"+(initial.employeeId()!=null?initial.employeeId():initial.adoptionId()));
  if(initial.employeeId()!=null){configs.lockDefaults(actor.tenantId(),initial.companyId());employees.lock(initial.employeeId());}else{var a=initial.content().adoption();publications.lock("adoption:"+actor.tenantId()+":"+store+":"+a.masterId());}
  var r=detail(actor,store,id);if(r.content().profile()!=null)configs.lock(r.content().profile().templateId());var replay=repository.replay(actor,store,id,c);if(replay.isPresent())return replay.get();if(r.revision()!=c.expectedRevision()||!r.hash().equals(c.expectedHash()))throw WorkforceException.conflict();String note=PayrollProfileValidation.text(c.note(),1000,Set.of("approve","reject").contains(c.action()));String nextStatus=switch(c.action()){case "submit"->{if(!Set.of("draft","withdrawn").contains(r.status()))throw WorkforceException.conflict();yield "submitted";}case "withdraw"->{if(!r.status().equals("submitted"))throw WorkforceException.conflict();yield "withdrawn";}case "approve","reject"->{if(!r.status().equals("submitted"))throw WorkforceException.conflict();yield c.action().equals("approve")?"approved":"rejected";}default->throw WorkforceException.invalid();};
  String stale=null;if(Set.of("submit","approve").contains(c.action())){try{if(!r.content().baselineHash().equals(drafts.baselineHash(actor,r.companyId(),r.employeeId(),r.content())))stale="SOURCE_BASELINE_CHANGED";else{if(r.content().profile()!=null)configs.assertTemplateAccess(actor.tenantId(),store,r.content().profile().templateId(),r.content().beforeProfile()!=null&&r.content().beforeProfile().templateId().equals(r.content().profile().templateId()),r.effectiveDate());drafts.frozen(actor,r);}}catch(WorkforceException e){if(e.status()==403)throw e;stale=e.code();}}
  if(stale!=null)nextStatus="stale";var event=new Event(stale==null?c.action():"stale",r.revision(),actor.actorId(),clock.instant(),stale==null?note:stale);var events=new ArrayList<Event>(r.events());events.add(event);var next=dated(actor.tenantId(),new Request(r.id(),r.companyId(),r.storeId(),r.employeeId(),r.effectiveDate(),r.adoptionId(),r.revision(),r.hash(),nextStatus,stale,r.content(),r.createdBy(),r.createdAt(),List.copyOf(events),"pending"));repository.save(actor.tenantId(),next,false);repository.event(actor.tenantId(),next,event);
  if(nextStatus.equals("approved"))apply(actor,next);audit.changed(actor,store,"pay-change."+event.action(),id,r,next);repository.command(actor,store,next,c);return next;
 }
 private void apply(CurrentActor actor,Request r){var c=r.content();if(c.supplemental()!=null)for(var proposal:c.supplemental())repository.proof(actor.tenantId(),r.companyId(),proof(actor,r,"supplemental",proposal.id(),proposal.settlementMonth(),r.revision()),proposal);if(c.profile()!=null){var p=c.profile();configs.lock(p.id());repository.proof(actor.tenantId(),r.companyId(),proof(actor,r,"profile",p.id(),null,p.version()),p);configs.saveProfile(actor.tenantId(),p);}for(var m:c.months()){var current=repository.approvedMonthly(actor.tenantId(),r.companyId(),r.employeeId(),YearMonth.parse(m.month()));long version=current.map(ApprovedMonth::version).orElse(0L)+1;var p=proof(actor,r,"monthly",r.employeeId(),m.month(),version);repository.proof(actor.tenantId(),r.companyId(),p,m.after());repository.approveMonth(actor.tenantId(),new ApprovedMonth(r.companyId(),r.employeeId(),m.month(),version,m.after(),p));}if(c.adoption()!=null){var old=c.adoption();var release=c.upgrade()==null?null:c.upgrade().targetRelease();var a=new TemplatePublicationDtos.Adoption(UUID.randomUUID(),old.masterId(),release==null?old.releaseVersion():release.version(),r.companyId(),r.storeId(),publications.latest(actor.tenantId(),r.storeId(),old.masterId()).map(TemplatePublicationDtos.Adoption::storeVersion).orElse(0L)+1,UUID.randomUUID(),release==null?old.name():release.name(),c.derivedRule(),actor.actorId(),clock.instant());var t=new PayrollDtos.SalaryTemplate(a.materializedTemplateId(),r.companyId(),a.name(),a.rule(),true,1,new PayrollDtos.TemplateGovernanceSource(a.id(),r.storeId(),a.masterId(),a.releaseVersion()));repository.proof(actor.tenantId(),r.companyId(),proof(actor,r,"template",t.id(),null,t.version()),t);configs.saveTemplate(actor.tenantId(),t);publications.adoptEffective(actor.tenantId(),a,r.effectiveDate());}}
 private Proof proof(CurrentActor actor,Request r,String kind,UUID subject,String month,long version){return new Proof(r.id(),r.revision(),r.hash(),kind,subject,month,version,actor.actorId(),clock.instant());}
 private Request dated(UUID tenant,Request r){String effect="pending";if(r.status().equals("approved")){var today=LocalDate.now(clock.withZone(ZoneId.of("Asia/Singapore")));var states=new ArrayList<String>();var proofs=repository.proofs(tenant,r.id());var c=r.content();if(c.supplemental()!=null&&!c.supplemental().isEmpty())states.add(r.effectiveDate().isAfter(today)?"future":"effective");if(c.profile()!=null){var saved=configs.findProfile(tenant,c.profile().id()).orElse(null);boolean replaced=!proofs.isEmpty()&&(saved==null||saved.version()!=c.profile().version());var current=PayChangeDrafts.effective(configs.employeeProfiles(tenant,r.companyId(),r.employeeId()),today);states.add(replaced?"history":r.effectiveDate().isAfter(today)?"future":proofs.isEmpty()||current!=null&&current.id().equals(c.profile().id())&&current.version()==c.profile().version()?"effective":"history");}for(var m:c.months()){var month=YearMonth.parse(m.month());var approved=repository.approvedMonthly(tenant,r.companyId(),r.employeeId(),month);boolean replaced=!proofs.isEmpty()&&(approved.isEmpty()||!approved.get().proof().requestId().equals(r.id()));states.add(replaced||month.atEndOfMonth().isBefore(today)?"history":month.atDay(1).isAfter(today)?"future":"effective");}if(c.adoption()!=null){var proof=proofs.stream().filter(p->p.kind().equals("template")).findFirst().orElse(null);if(proof==null)states.add(r.effectiveDate().isAfter(today)?"future":"effective");else{var template=configs.findTemplate(tenant,proof.subjectId()).orElseThrow();var at=publications.currentAt(tenant,r.storeId(),c.adoption().masterId(),r.effectiveDate().isAfter(today)?r.effectiveDate():today).orElse(null);states.add(at==null||!at.materializedTemplateId().equals(template.id())?"history":r.effectiveDate().isAfter(today)?"future":"effective");}}effect=states.contains("effective")?"effective":states.contains("future")?"future":"history";}return new Request(r.id(),r.companyId(),r.storeId(),r.employeeId(),r.effectiveDate(),r.adoptionId(),r.revision(),r.hash(),r.status(),r.staleReason(),r.content(),r.createdBy(),r.createdAt(),r.events(),effect);}
}
